          'ஒவ்வொரு வேரியன்ட், டோன், தீமிலும் உரை 4.5:1 கான்ட்ராஸ்ட் விகிதத்தை எட்டுகிறது; வண்ணத் தட்டு ஜெனரேட்டர் இதைக் கட்டாயமாக்குகிறது.',
