            text: 'ஒவ்வொரு பொத்தானும் அதே டயலாக்கை <code>bouncy</code> ஸ்பிரிங்குடன், ஆனால் வேறொரு <code>enter</code> முன்னமைவுடன் திறக்கிறது. அது எப்படி வந்தாலும், போகும்போது விரைவாக மங்கி மறைகிறது.',
