          'ஒவ்வொரு டோஸ்டும் தோன்றும்போது அறிவிக்கப்படுகிறது: இயல்பாக (polite), danger என்றால் உடனடியாக (assertive). டோஸ்ட்கள் ஒருபோதும் ஃபோகஸை எடுப்பதில்லை.',
          'அடுக்கின் மேல் மவுஸ் அல்லது ஃபோகஸ் இருக்கும்வரையும், பக்கம் மறைந்திருக்கும்வரையும் டைமர்கள் நிற்கின்றன; promise-க்காகக் காத்திருக்கும் டோஸ்ட்களுக்கு நேர வரம்பு இல்லை.',
