              loading: 'முடிவுகள் வந்துகொண்டிருக்கும்போது ஏற்றுதல் வரிசையைக் காட்டுகிறது.',
              hints: 'பயன்படுத்த வேண்டிய விசைகளை அடியில் காட்டுகிறது.',
              virtual:
                'பார்வையில் உள்ள வரிசைகளை மட்டுமே ரெண்டர் செய்கிறது: எப்போதும், ஒருபோதும் இல்லை, அல்லது <code>auto</code> என்றால் 200 வரிசைகளுக்கு மேல்.',
              label: 'டயலாக்கின், அதன் தேடல் புலத்தின் அணுகல் பெயர்.',
