              'ஒரு நிகழ்வு. நேரமுள்ள நிகழ்வின் முடிவு அதில் சேராது; முழுநாள் நிகழ்வின் முடிவு அதன் கடைசி நாள்.',
            members: {
              'id, title': 'அதன் சாவியும், அது காட்டுவதும்.',
              'start, end': 'தேதிகளும் நேரங்களும்; முழுநாள் நிகழ்வுகளுக்குத் தேதிகள் மட்டும்.',
              allDay: 'இயல்பாக, <code>start</code>-இல் நேரம் இல்லையா என்பது.',
              tone: 'அதன் நிறம்.',
              editable: 'நிகழ்வு அட்டவணை எதைச் சொன்னாலும், அதை நகர்த்த முடியுமா என்பது.',
              data: 'அதனுடன் வைத்திருக்க வேண்டிய வேறு எதுவும்.',
            },
