        apiDescription:
          'Needless UI இன்புட் மாஸ்க்கின் API குறிப்பு: nuiMask டைரக்டிவ், அதன் டோக்கன்களும் மதிப்பும், கார்டு எண்கள், IBAN-களுக்கான உதவி ஃபங்ஷன்கள்.',
