            text: 'பெயரிட்ட வண்ண மாதிரிகள், வண்ணத்தின் மேல் வெள்ளை உரையின் கான்ட்ராஸ்ட்: வெளிர் வண்ணத்தைத் தேர்ந்தெடுத்தால் AA தோல்வியடைகிறது.',
