            kind: 'p',
            html: 'சிஸ்டம் குறைந்த இயக்கத்தைக் கேட்கும்போது, ஸ்பிரிங்குகள் உடனடி மாற்றமாகச் சுருங்குகின்றன; அழுத்த விளைவுகளும் நுழைவு அனிமேஷன்களும் அசைவதை நிறுத்துகின்றன. அடர்த்தி எந்தக் கட்டுப்பாட்டையும் WCAG 2.2-இன் 24px இலக்கு அளவுக்குக் கீழே குறைப்பதில்லை; எந்த முன்னமைவும் வண்ணங்களைத் தொடுவதில்லை, எனவே ஒவ்வொரு கான்ட்ராஸ்ட் சரிபார்ப்பும் இன்னும் செல்லுபடியாகும். <code>corner-shape</code> ஆதரவு இல்லாத உலாவிகள் எல்லா மூலைகளையும் வட்டமாக வரைகின்றன.',
